n,m,q=list(map(int,input().split()))
a=[ "p" for i in range(n) ]
for _ in range(n):
	l=input().split()
	a[_]=l
dif = [ (1,0), (-1,0), (0,1), (0,-1) ]#down,upward,right,left(i,j)
mark = [ [False for j in range(m)] for i in range(n) ]
parent= [ [0 for j in range(m)] for i in range(n) ]
def valid(x,y):
	return y >= 0 and x >= 0 and y < m and x < n

def dfs(start):
	global component_id
	c=1
	q=[]
	q.append(start)

	while q :
		top=q.pop(0)
		#c+=1
		parent[top[0]][top[1]]=component_id
		mark[top[0]][top[1]]=True
		#print "top",top

		for k in dif:
			if (valid(top[0]+k[0],top[1]+k[1]))and (a[top[0]+k[0]][top[1]+k[1]]=="1" ) and mark[top[0]+k[0]][top[1]+k[1]]==False:
			   #print top[0]+k[0],top[1]+k[1] 
			   mark[top[0]+k[0]][top[1]+k[1]]=True
			   parent[top[0]+k[0]][top[1]+k[1]]=component_id
			   c+=1
			   q.append((top[0]+k[0],top[1]+k[1]))


	return c
component_id=1
co=0 
d={}
f={}  
for i in range(n):
	for j in range(m):
		if a[i][j]=="1":
			 co+=1

			 if mark[i][j]==False:
			  tI=dfs((i,j))
			  d[component_id]=tI
			  f[component_id]=True
			  component_id+=1


while q!=0:
